# Batch 04 — Chapter IV, Sections 4–5 (Articles 37–43).
def rt(u, origin, cp, rtype, obj, fn, mod, cond="", note="", deriv="direct", unres="", flag="", acc="", ext_dep="", dep=""):
    return qr(u, origin, cp, rtype, obj, fn, mod, cond=cond, deriv=deriv, type_note=note, unresolved=unres, flag=flag, acc=acc, ext=ext_dep, dep=dep)
CTRL, PROC, DS, SA = "controller", "processor", "data subject", "supervisory authority"
ASSOC = pd("association or body representing categories of controllers or processors", "position_type", "A37.P4;A40.P2", note="Private collective bodies; instances not created.")
MON = pd("code-monitoring body (accredited, Art.41)", "position_type", "A41.P1", ntype="N0 (position type specified; instances arise by accreditation by the competent SA)", note="Body with expertise, accredited by the competent supervisory authority to monitor compliance with a code of conduct.")
CB = pd("certification body (Art.43)", "position_type", "A43.P1", ntype="N0 (type specified; instances arise by accreditation)", note="Issues and renews certification; accredited by the competent SA and/or by the national accreditation body.")
NAB = pd("national accreditation body (named under Regulation (EC) No 765/2008)", "position_type", "A43.P1.ptb", ntype="constituted outside W (external reference)", note="Position type referenced; constitution depends on Regulation (EC) No 765/2008 (EXT).", flag="external-constitution")
REG_CODES = pd("register of approved codes of conduct, amendments and extensions (Board)", "device", "A40.P11", ntype="N2 (obligation to collate in a register — not N1)", note="Duty of the Board to collate and publish; the register is not 'established' by an N1 provision in this unit.", flag="N2-register")
REG_CERT = pd("register of certification mechanisms and data protection seals and marks (Board)", "device", "A42.P8", ntype="N2 (obligation to collate in a register — not N1)", note="Corrigendum 2018 removes the parallel Board-register sentence from Art.43(6); the register duty remains in 42(8).", flag="N2-register")
SEAL = pd("European Data Protection Seal (common certification)", "device", "A42.P5", ntype="N4/N3-like (possible outcome: 'this may result in a common certification')", note="Named common certification that may result where criteria are approved by the Board.", flag="DEV-threshold")

# ---- Article 37 (DPO designation)
n = na("A37.P1", CTRL + " and " + PROC, "designate a data protection officer", "data protection officer", "authorization/designation", "obligation", cond="(a) processing by a public authority or body (except courts acting in judicial capacity); (b) core activities requiring regular and systematic large-scale monitoring of data subjects; (c) core activities consisting of large-scale processing of special categories or criminal-conviction data (corrigendum 2018: 'or')", ntype="N2-designation", note="Obligation to designate an office-holder; the office is specified at type level in Arts 37–39; the instance arises by designation.", flag="N2-designation")
screen("A37.P1", "Yes", "operative-assignment; position-defining", na=[n], pos=[DPO], status="Extracted", note="Corrigendum applied at point (c).")
n = na("A37.P2", "group of undertakings", "appoint a single data protection officer", "DPO", "authorization/designation", "permission", cond="DPO easily accessible from each establishment")
screen("A37.P2", "Yes", "operative-assignment", na=[n], status="Extracted")
