screen("A37.P3", "Yes", "operative-assignment", na=[n], status="Extracted")
n = na("A37.P4", CTRL + " / " + PROC + " / associations and bodies representing categories", "designate a DPO (may; shall where required by Union or Member State law); the DPO may act for such associations and bodies", "DPO", "authorization/designation", "permission", cond="cases other than 37(1); mandatory where Union or Member State law requires", ntype="N2-designation (conditional on national/Union law)")
screen("A37.P4", "Yes", "operative-assignment", na=[n], pos=[ASSOC], status="Extracted")
n = na("A37.P5", CTRL + " and " + PROC, "designate the DPO on the basis of professional qualities, expert knowledge of data protection law and practices, and ability to fulfil the Art.39 tasks", "DPO selection criteria", "authorization/designation", "obligation")
screen("A37.P5", "Yes", "operative-assignment", na=[n], status="Extracted")
