screen("A37.P7", "Yes", "relation-bearing", qr=q, status="Extracted")

# ---- Article 38 (position of DPO)
q = [rt("A38.P1", CTRL + " / " + PROC, DPO, "representation/participation", "DPO involved properly and in a timely manner in all issues relating to personal data protection", "participation", "obligation", note="gov-direction: controller/processor involve DPO")]
screen("A38.P1", "Yes", "relation-bearing", qr=q, status="Extracted")
q = [rt("A38.P2", CTRL + " / " + PROC, DPO, "authority/control", "support: necessary resources, access to personal data and processing operations, maintenance of expertise", "implementation (support)", "obligation", note="resource and access guarantee; limits control")]
