q = [rt("A38.P4", DPO, DS, "representation/participation", "data subjects may contact the DPO on all issues related to processing and the exercise of rights", "participation/contact", "entitlement", note="entitlement of data subjects; gov-direction: data subject → DPO as contact point")]
screen("A38.P4", "Yes", "relation-bearing", qr=q, status="Extracted")
n = na("A38.P5", DPO, "be bound by secrecy or confidentiality concerning the performance of tasks, in accordance with Union or Member State law", "confidentiality", "implementation", "obligation")
screen("A38.P5", "Yes", "operative-assignment", na=[n], status="Extracted")
n = na("A38.P6", CTRL + " / " + PROC, "ensure that other tasks and duties of the DPO do not result in a conflict of interests", "conflict of interests", "implementation", "obligation", cp_status="none", counterpart=DPO)
screen("A38.P6", "Yes", "operative-assignment", na=[n], status="Extracted", note="Includes permission for the DPO to fulfil other tasks.")

# ---- Article 39 (tasks of DPO)
q = [rt("A39.P1", DPO, CTRL + " / " + PROC + " (and employees carrying out processing)", "information/reporting", "inform and advise on obligations under the Regulation and other data protection provisions (a); advice on the DPIA and monitoring of its performance (c)", "interpretation/advice", "obligation", note="internal advisory function"),
     rt("A39.P1", DPO, CTRL + " / " + PROC, "oversight/supervision", "monitoring compliance with the Regulation, other provisions and policies, including assignment of responsibilities, awareness-raising, training and related audits (b)", "monitoring", "obligation", note="internal compliance-monitoring function (self-regulatory oversight within the regulated organisation)"),
     rt("A39.P1", DPO, SA, "information/reporting", "cooperation with the supervisory authority and contact point on processing issues including prior consultation under Art.36 (d)(e)", "cooperation/coordination", "obligation", note="DPO as interface between the organisation and the SA")]
