screen("A40.P1", "Yes", "operative-assignment", na=[n], pos=[BOARD], status="Extracted")
n = na("A40.P2", ASSOC, "prepare, amend or extend codes of conduct specifying the application of the Regulation (matters (a)-(k))", "codes of conduct", "rule-making (private standard-setting)", "permission", cp_status="none", dep="approved code of conduct (Art.40)", note="Private self-regulatory standard-setting by representative bodies; effects depend on approval under 40(5).")
screen("A40.P2", "Yes", "operative-assignment", na=[n], status="Extracted")
