q = [rt("A40.P5", ASSOC, SA + " (competent under Art.55)", "information/reporting", "submission of the draft code, amendment or extension", "information provision", "obligation", cond="intention to prepare/amend/extend a code"),
     rt("A40.P5", SA + " (competent under Art.55)", ASSOC, "verification/assurance", "opinion on whether the draft complies with the Regulation", "verification/assurance", "obligation", note="gov-direction: SA verifies association's draft"),
     rt("A40.P5", SA + " (competent under Art.55)", ASSOC, "delegation/authorization", "approval of the draft code, amendment or extension if it provides sufficient appropriate safeguards", "authorization", "obligation", cond="SA finds sufficient appropriate safeguards", note="approval confers the code's 'approved' status; consequences for use of the code under Arts 24, 28, 32, 35")]
