screen("A40.P6", "Yes", "operative-assignment", na=[n], status="Extracted")
q = [rt("A40.P7", SA + " (competent under Art.55)", BOARD, "information/reporting", "submission of the draft code, before approval, in the procedure of Art.63", "cooperation/coordination (consistency)", "obligation", cond="draft code relates to processing activities in several Member States", dep="consistency mechanism (Art.63)"),
     rt("A40.P7", BOARD, SA + " (competent under Art.55)", "verification/assurance", "opinion on whether the draft complies with the Regulation or provides appropriate safeguards (transfers)", "verification/assurance", "obligation", cond="after submission under 40(7)", note="gov-direction: Board verifies draft submitted by SA", dep="consistency mechanism (Art.63)")]
