# ---- Article 41 (monitoring bodies)
q = [rt("A41.P1", SA + " (competent)", MON, "delegation/authorization", "accreditation of a body with appropriate expertise to monitor compliance with a code of conduct", "authorization (accreditation)", "competence", cond="without prejudice to the SA's own tasks and powers under Arts 57–58; body has appropriate expertise", note="gov-direction: SA accredits monitoring body; the unit states 'may be carried out by a body ... accredited'"),
     rt("A41.P1", MON, CTRL + " / " + PROC + " adhering to the code", "oversight/supervision", "monitoring of compliance with the code of conduct", "monitoring", "permission", cond="body accredited; code approved", note="gov-direction: monitoring body monitors adherents (private oversight of code compliance)")]
